// Watchdog логбука. Найважливіша перевірка — «пристрій мовчить»:
// тиха втрата даних руйнує base year, а його не можна відтворити заднім числом.

const c = $input.first().json;
const devices = ($('Traccar Devices').all() || []).map(i => i.json).flat();

const alerts = [];
const now = Date.now();

// 1. пристрій мовчить
if (devices.length === 0) {
  // мовчимо, доки трекер не очікується: інакше алерт спамив би кожні 6 год
  // усі місяці, поки залізо в дорозі
  if (+c.expected_devices > 0) {
    alerts.push('🔌 <b>Пристрій зник з Traccar</b> — його прописано в fleet.vehicles, але в Traccar його немає.');
  }
} else {
  for (const d of devices) {
    if (!d.lastUpdate) {
      alerts.push(`🔌 <b>${d.name}</b> — жодної позиції з моменту реєстрації.`);
      continue;
    }
    const hours = (now - new Date(d.lastUpdate).getTime()) / 3600000;
    if (hours > 36) {
      alerts.push(`🚨 <b>${d.name} мовчить ${Math.round(hours)} год</b> — перевір трекер. Пропуски в логбуку не відновлюються.`);
    }
  }
}

// 2. некласифіковані поїздки
if (+c.stale_unclassified > 0) {
  alerts.push(`❓ <b>${c.stale_unclassified}</b> поїздок без класифікації понад 72 год (${c.unclassified_km} км) — натисни кнопку під карткою. При перевірці це трактується не на твою користь.`);
}

// 3. бізнес-поїздки без мети — CRA вимагає поле «мета»
if (+c.business_no_purpose > 0) {
  alerts.push(`📝 <b>${c.business_no_purpose}</b> бізнес-поїздок без мети:\n${c.no_purpose_list || ''}\n\n<i>Закрити: номер і мета одним рядком, наприклад</i> <code>15 замір даху</code>`);
}

// 4. пробіг без жодної заправки
if (+c.km_since_last_fuel > 500) {
  alerts.push(`⛽ <b>${c.km_since_last_fuel} км</b> без жодного чека на пальне. Готівка без чека = ні вирахування, ні HST ITC, ні зменшення benefit.`);
}

if (+c.fuel_without_receipt > 0) {
  alerts.push(`🧾 <b>${c.fuel_without_receipt}</b> заправок без прикріпленого чека.`);
}

// 5. дедлайн відшкодування — 45 днів після кінця року
const d = new Date();
const month = d.getMonth() + 1, day = d.getDate();
if (month === 1 && day >= 20 && +c.pending_reimbursements > 0) {
  alerts.push(`⏳ <b>${c.pending_reimbursements}</b> невідшкодованих особистих оплат. Дедлайн 14 лютого — інакше operating benefit не обнуляється.`);
}

// 6. одометр на кінець року
if (month === 12 && day >= 28 && +c.have_year_end === 0) {
  alerts.push('📸 <b>Немає фото одометра на кінець року.</b> Це перше, що просять при перевірці.');
}

if (alerts.length === 0) return [];

return [{ json: {
  chat_id: c.chat_id,
  text: '<b>🚐 Логбук Pacifica</b>\n\n' + alerts.join('\n\n')
} }];
